import json,sys,random
sys.path.insert(0,'/workspace/t'); sys.path.insert(0,'/workspace')
from wire import v,envelope,datagram
from diff import cmp

SIDS=[0,1,2,3,4,8,12,16,20,24,5,9,13,17,6,10,14]

def rnd_frame(r):
    t=r.choice([0x00,0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08,0x09,0x0a,0x0b,0x0c,0x0d,0x0e,0x0f,
                0x10,0x11,0x12,0x13,0x14,0x15,0x16,0x17,0x18,0x19,0x1a,0x1b,0x1c,0x1d,0x1e,0x30,0x31,
                0x1f,0x40,0x2a,0x62])
    if 0x08<=t<=0x0f:
        sid=r.choice(SIDS)
        out=bytes([t])+v(sid)
        if t&4: out+=v(r.choice([0,0,0,1,3,5,7,10,2**62-1]))
        data=bytes(r.randrange(256) for _ in range(r.choice([0,0,1,1,2,3,5])))
        if t&2: out+=v(r.choice([len(data),len(data),len(data)+3,200]))
        return out+data
    if t in (0x02,0x03):
        largest=r.choice([0,3,10,50,2**62-1]); first=r.choice([0,0,1,largest])
        if first>largest: first=largest
        pairs=[]
        low=largest-first
        for _ in range(r.choice([0,0,1,2,3])):
            gap=r.choice([0,0,1,3]); rng=r.choice([0,1,2,5,low])
            if rng>low: rng=low
            if low<gap+2: gap=0
            if low>=2 and rng<=low-gap-2:
                pairs.append((gap,rng)); low=low-gap-2-rng
            else: break
        out=bytes([t])+v(largest)+v(r.choice([0,7]))+v(len(pairs))+v(first)
        for g,x in pairs: out+=v(g)+v(x)
        if t==0x03: out+=v(r.randrange(4))+v(r.randrange(4))+v(r.randrange(4))
        return out
    if t==0x06: return bytes([t])+v(r.choice([0,0,0,1,4,9]))+v(r.choice([0,0,1,2]))+bytes(r.randrange(256) for _ in range(r.choice([0,1,2,3])))
    if t==0x04: return bytes([t])+v(r.choice(SIDS))+v(r.choice([0,11,17]))+v(r.choice([0,1,3,5,7,20,2**62-1]))
    if t==0x05: return bytes([t])+v(r.choice(SIDS))+v(r.choice([0,13,19]))
    if t in (0x11,0x15): return bytes([t])+v(r.choice(SIDS))+v(r.choice([0,1,10,100]))
    if t==0x18:
        return bytes([t])+v(r.choice([0,1,2,3,4]))+v(r.choice([0,0,1,2,3,5]))+bytes([r.choice([1,1,2,3,0,21])])+bytes([r.randrange(4)+1])+bytes(16)
    if t==0x19: return bytes([t])+v(r.choice([0,1,2,3,0,9]))
    if t in (0x1a,0x1b): return bytes([t])+bytes(r.randrange(256) for _ in range(r.choice([8,8,8,7])))
    if t==0x1c: return bytes([t])+v(r.randrange(5))+v(r.choice([0,1]))+v(r.choice([0,0,2]))+b're'
    if t==0x1d: return bytes([t])+v(r.randrange(5))+v(r.choice([0,0,2]))+b're'
    if t==0x30: return bytes([t])+bytes(r.randrange(256) for _ in range(r.randrange(0,4)))
    if t==0x31: return bytes([t])+v(r.choice([0,1,4]))+b'ab'
    if t in (0x10,0x12,0x13,0x14,0x16,0x17): return bytes([t])+v(r.choice([0,3,7,2**60,2**60+1]))
    return bytes([t])+v(r.randrange(4))

def gen(r):
    nc=r.choice([1,2,3])
    cids=[bytes([0xaa]),bytes([0xbb]),bytes([0xcc])][:nc]
    lim=dict(connection=r.choice([3,10,40,1000,2**62-1]),stream=r.choice([3,10,40,2**62-1]),
             bidi=r.choice([1,2,4,8]),uni=r.choice([1,2,4,8]),cids=r.choice([2,3,4]))
    loc=dict(bidi=r.choice([1,2,3]),uni=r.choice([1,2,3]),cids=[c.hex() for c in cids])
    peer=dict(cid='cc',token='00'*16)
    seeds=dict(I=r.choice([None,None,0,5,9]),H=r.choice([None,None,0,3]),A=r.choice([None,None,0,4,7,100]))
    events=[]
    pn={'I':0,'H':0,'A':0}
    for _ in range(r.randrange(0,10)):
        if r.random()<0.2:
            events.append({'keys':r.sample(['I','H','A'],r.randrange(0,4))})
            continue
        wire=b''; auth=[]
        for _ in range(r.randrange(1,4)):
            lvl=r.choice(['I','H','A','A','A'])
            frames=b''.join(rnd_frame(r) for _ in range(r.randrange(0,5)))
            width=r.choice([1,1,1,2,4])
            pn[lvl]+=r.choice([0,1,1,1,2,3,7])
            ann=r.choice([None,0,0,0,0,1,1,2,3,5])
            phase=r.choice([0,1])
            if ann is not None and r.random()<0.7: phase=ann&1
            cid=r.choice(cids) if lvl=='A' else bytes([r.randrange(3)])
            e=envelope(lvl,pn[lvl],frames,cid=cid,scid=bytes([0xbb]),token=b'' if r.random()<0.6 else b'12',width=width,phase=phase)
            if r.random()<0.07 and len(e)>2: e=e[:len(e)-r.randrange(1,3)]
            wire+=e
            auth.append(ann)
        if r.random()<0.06: wire=bytes(r.randrange(256) for _ in range(r.randrange(0,12)))
        events.append({'datagram':{'wire':wire.hex(),'auth':auth}})
    return dict(limits=lim,local=loc,peer=peer,received=seeds,events=events)

r=random.Random(int(sys.argv[1]))
N=int(sys.argv[2])
bad=0
for i in range(N):
    tr=gen(r)
    if not cmp({'traces':[tr]},'seed%d case%d'%(int(sys.argv[1]),i)): bad+=1
    if bad>2: break
print('done bad=',bad)
